 FrameworkElement RecentStack(List<RecentEntry> entries){var r=cfg.Recents;var row=new StackPanel{Orientation=Orientation.Horizontal};var iconsPanel=new Canvas{Width=Math.Min(r.StackCount,entries.Count)*24+16,Height=40};for(int i=0;i<Math.Min(r.StackCount,entries.Count);i++){var image=new Image{Width=26,Height=26,Uid="RecentIcon"};QueueIcon(image,entries[i].Target);RecentLayer(image,"Icon",r.IconX,r.IconY);var tile=new Border{Width=38,Height=38,CornerRadius=new CornerRadius(9),Background=SurfaceBrush(Parse(r.ItemBackground,baseColor),r.ItemOpacity,r.ItemGlass),Child=image};RecentLayer(tile,"Items",r.ItemsX,r.ItemsY);Canvas.SetLeft(tile,i*24);iconsPanel.Children.Add(tile);}row.Children.Add(iconsPanel);var button=Action(entries.Count+" items",()=>{});button.FontSize=r.CountSize;button.Foreground=new SolidColorBrush(Parse(r.CountColor,Colors.White));button.Background=SurfaceBrush(Parse(r.CountBackground,baseColor),r.CountOpacity,false);RecentLayer(button,"Count",r.CountX,r.CountY);row.Children.Add(button);var popup=new Popup{PlacementTarget=button,Placement=PlacementMode.Bottom,AllowsTransparency=true,StaysOpen=false};var list=new StackPanel();foreach(var entry in entries){var item=entry;var line=new DockPanel{Height=r.DropdownRowHeight};var image=new Image{Width=r.IconSize,Height=r.IconSize,Uid="RecentDropdownIcon",Margin=new Thickness(8)};QueueIcon(image,item.Target);RecentLayer(image,"DropdownIcon",r.DropdownIconX,r.DropdownIconY);DockPanel.SetDock(image,Dock.Left);line.Children.Add(image);if(r.DropdownTimes){var age=TimeSpan.FromTicks(Math.Max(0,DateTime.UtcNow.Ticks-item.Time));var time=Text(age.TotalMinutes<1?"now":age.TotalHours<1?((int)age.TotalMinutes)+"m":age.TotalDays<1?((int)age.TotalHours)+"h":((int)age.TotalDays)+"d",11,mutedBrush);time.VerticalAlignment=VerticalAlignment.Center;DockPanel.SetDock(time,Dock.Right);RecentLayer(time,"DropdownTime",r.DropdownTimeX,r.DropdownTimeY);line.Children.Add(time);}var label=Text(item.Name,13);label.VerticalAlignment=V